"""Summarize per-sample genotype statistics from a VCF."""


def summarize_gt(records, samples):
    """Return per-sample stats given parsed VCF records and sample names.

    Each record is a list of FORMAT/sample fields: [FORMAT, s1, s2, ...].
    Returns {sample: {"callable": n, "het": n, "hom_alt": n, "alt_alleles": n}}.
    """
    stats = {
        s: {"callable": 0, "het": 0, "hom_alt": 0, "alt_alleles": 0}
        for s in samples
    }

    for record in records:
        fmt_keys = record[0].split(":")
        gt_index = fmt_keys.index("GT")
        for sample, field in zip(samples, record[1:]):
            parts = field.split(":")
            if gt_index >= len(parts):
                continue
            gt = parts[gt_index]
            if "." in gt:
                continue  # missing genotype excluded from every statistic

            alleles = gt.replace("|", "/").split("/")
            stats[sample]["callable"] += 1

            a1, a2 = alleles[0], alleles[1] if len(alleles) > 1 else alleles[0]

            if a1 != a2:
                stats[sample]["het"] += 1
            elif a1 == "1":
                stats[sample]["hom_alt"] += 1

            stats[sample]["alt_alleles"] += sum(
                1 for a in alleles if a == "1"
            )

    return stats


def parse_vcf(text):
    """Parse minimal VCF text -> (samples, records). Records keep FORMAT+samples."""
    samples = []
    records = []
    for line in text.splitlines():
        line = line.rstrip("\n")
        if not line:
            continue
        if line.startswith("#CHROM"):
            cols = line.split("\t")
            samples = cols[9:]
        elif not line.startswith("#"):
            cols = line.split("\t")
            records.append(cols[8:])
    return samples, records

