import pytest

from gt_stats import parse_vcf, summarize_gt


FIXTURE = "\n".join(
    [
        "##fileformat=VCFv4.2",
        "#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tS1\tS2\tS3",
        "chr1\t100\t.\tA\tG\t.\tPASS\t.\tGT\t0/1\t1/1\t0/0",
        "chr1\t200\t.\tC\tT\t.\tPASS\t.\tGT\t1/1\t0/1\t0/1",
        "chr2\t300\t.\tG\tA\t.\tPASS\t.\tGT\t0/0\t0/0\t1/1",
        "chr2\t400\t.\tT\tC\t.\tPASS\t.\tGT\t./.\t0/1\t0/0",
    ]
)


@pytest.fixture()
def stats():
    samples, records = parse_vcf(FIXTURE)
    return summarize_gt(records, samples)


def test_s1(stats):
    assert stats["S1"] == {
        "callable": 3,
        "het": 1,
        "hom_alt": 1,
        "alt_alleles": 3,
    }


def test_s2(stats):
    assert stats["S2"] == {
        "callable": 4,
        "het": 2,
        "hom_alt": 1,
        "alt_alleles": 4,
    }


def test_s3(stats):
    assert stats["S3"] == {
        "callable": 4,
        "het": 1,
        "hom_alt": 1,
        "alt_alleles": 3,
    }

